$_MODULE['<{ntbackupandrestore}prestashop>faq_51452b6d1f8511cf289eb01753eda3bb'] = 'اتوماسیون توسط 2N روزانه انجام می شود';
$_MODULE['<{ntbackupandrestore}prestashop>faq_42027eaa203032a09ccc5048897c677c'] = 'به نظر نمی رسد اتوماسیون توسط 2N دیگر کار کند ، چه کاری می توانم انجام دهم؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_ffebb8fcef9bdccc3aeac353e6d78be7'] = 'لطفا دوباره سعی کنید آن را ذخیره کنید';
$_MODULE['<{ntbackupandrestore}prestashop>faq_41906c69303e903c986fde8f7cb34665'] = 'نسخه پشتیبان با خطایی به پایان رسید که نشان می دهد فضای کافی برای پشتیبان گیری وجود ندارد ، اما من می دانم که وجود دارد. چرا من این خطا را دارم؟ ';
$_MODULE['<{ntbackupandrestore}prestashop>faq_8bdbb9087cc2864414759889f6d22307'] = 'این خطا می تواند توسط محدودیت سرور شما ایجاد شود. برخی از سرورها (32 بیتی) اجازه پشتیبان گیری بیش از 2 گیگابایت را نمی دهند. در این حالت، می توانید از گزینه پیشرفته برای کاهش اندازه فایل پشتیبان استفاده کنید. نسخه پشتیبان در قسمت های کوچکتری که توسط سرور شما پذیرفته می شود، تهیه می شود. به عنوان مثال، شما می توانید 1500 را به عنوان محدودیت اندازه برای اندازه فایل پشتیبان خود انتخاب کنید. توجه داشته باشید که اگر می خواهید فروشگاه خود را بازیابی کنید، تمام قسمت ها لازم است.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_afde1c7273735610102d9f166386b91e'] = 'از کجا می توانم نسخه پشتیبان را در سرور خودم پیدا کنم؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c99296863a8cfebedbf941a80b149eb3'] = 'می توانید به صورت پیش فرض نسخه پشتیبان خود را در پوشه ماژول / ntbackupandrestore / backup / یا در پوشه هایی که با پیکربندی پیشرفته مشخص کرده اید، پیدا کنید.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6162f1ad35f8d68d2ad18e65d6af12ca'] = 'از کجا می توانم پایگاه داده را در نسخه پشتیبان پیدا کنم؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_259f134b1c3cb0f4211d27812fb4f339'] = 'هنگامی که یک نسخه پشتیبان کامل تهیه می کنید، پایگاه داده شما با تمام فایل های دیگر در فایل پشتیبان ذخیره می شود. اگر می خواهید بررسی کنید، فایل پشتیبان خود را در رایانه تان از حالت فشرده خارج کنید، می توانید dump.sql را در پوشه ماژول / ntbackupandrestore / backup / پیدا کنید';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d50856eaf5567a344aafac6b6629a581'] = 'چگونه می توانم معتبر بودن نسخه پشتیبان را بررسی کنم؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d2a25247fc786e9f6a27212ee9aed0b8'] = 'بهترین راه برای اطمینان از معتبر بودن نسخه پشتیبان تهیه شده این است که آن را در جای دیگری بازیابی کنید. به عنوان مثال ، در یک دامنه جدید و پایگاه داده جدید یا در رایانه خود با نرم افزارهای Wamp ، Mamp ، Easyphp یا سایر سرورهای محلی.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_b26bae87fdb843d75a120d12fe51ffa6'] = 'چگونه می توان نسخه پشتیبان خود را بازیابی کرد؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_84d3c56657e5438d10f92c3d36c5cf8b'] = 'برای بازیابی نسخه پشتیبان خود باید:';
$_MODULE['<{ntbackupandrestore}prestashop>faq_261aa829c8bd1bd4216bf09dc76f7326'] = 'انتخاب کنید که فروشگاه شما کجا بازیابی شود. در مکان جدید (دامنه جدید و پایگاه داده جدید) برای کپی/انتقال یا در ریشه فروشگاه فعلی خود برای جایگزینی آن.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0c02578d80e75b15e3c2fafda964bfe4'] = 'نسخه پشتیبان و اسکریپت بازیابی خود را در مکان انتخاب شده قرار داده';
$_MODULE['<{ntbackupandrestore}prestashop>faq_967e66ec729f29106f185bf0e5c9c267'] = 'با استفاده از مرورگر وب خود به اسکریپت بازیابی دسترسی پیدا کنید';
$_MODULE['<{ntbackupandrestore}prestashop>faq_96c158c212b69d93f4bf51a208b7c6b0'] = 'اعتبار دسترسی به پایگاه داده که در آن داده ها بازیابی می شود را پر کنید.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3438a63edfc1456e8bff9b8a75f0f8c2'] = 'اختیاری: در صورت نیاز ، گزینه های پیشرفته را پیکربندی کنید';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0b20e24f98a55bf66d6fe76363284591'] = 'بازیابی را شروع کنید. توجه داشته باشید که فایل های موجود در نسخه پشتیبان، فایل های موجود را بازنویسی می کنند و پایگاه داده نسخه پشتیبان شما جایگزین پایگاه داده قبلی می شود.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6510898b2f7a8fa6fe8aeafb9ea5ca4d'] = 'برای بازیابی فروشگاه، آیا ابتدا باید پرستاشاپ خالی را نصب کنم؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_2f8b950c8cb11678dd68bd1050f15034'] = 'برای بازیابی نیازی به نصب پرستاشاپ خالی ندارید. شما فقط به فایل پشتیبان و اسکریپت بازیابی خود احتیاج دارید.';
