$_MODULE['<{ntbackupandrestore}prestashop>faq_d22b5ed685107fdea35dd423a0adc8e4'] = 'پشتیبان گیری کامل شامل یک کپی دقیق از وب سایت شما، که به معنی تمام فایل ها و داده های خود را، به جز فایل ها و داده های کم بهره (حافظه نهان، سیاهههای مربوط ...) که ذخیره نمی شود چرا که اندازه آنها بزرگ است و آنها از استفاده کمی در طول بازگرداندن. با این وجود می توانید به ماژول بگویید که آنها را در گزینه های پیشرفته ذخیره کند.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c7b627aacbd45fc86611dc65afcd11fc'] = 'من فضای کافی بر روی سرور من برای پشتیبان گیری، آیا می توانم آن را به طور مستقیم به یکی از حساب های از راه دور من ارسال (%1$s، %2$s...)؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0ec06b6f186a84a008827f4ee4efdff2'] = 'قبل از اینکه فایل پشتیبان به یک مکان دیگر ارسال شود، فایل پشتیبان باید روی سرور شما ایجاد شود. همچنین باید حداقل فضای لازم براي يک فایل پشتيبان داشته باشيد. شما می توانید در پیکربندی پیشرفته گزینه حذف خودکار پشتیبان محلی را فعال کنید تا در صورتی که فایل پشتیبان به یک حساب دیگر فرستاده شد، به طور خودکار از روی هاست شما حذف شود. اگر فضای کافی برای ایجاد یک نسخه پشتیبان نداريد، مي توانيد ارسال مستقيم (بدون پشتيبان گیری محلی) به سرور دیگر (به جز FTP و Box) را فعال نماييد اما در اين حالت فایل پشتيبان فشرده نخواهد شد.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_50fe9d94822e8a6d1ed52600d8c071cc'] = 'چگونه ماژول را به روزرسانی کنیم؟';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c45a02babc859c783cc1a5b21b62cdfd'] = 'شما نیاز به دانلود آخرین نسخه از ماژول از whre شما آن را خریداری شده است.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_cf832f19d14486b25d11aaf8e9cc016d'] = 'سپس در backoffice از فروشگاه خود را، در ماژول > مدیریت ماژول ها، با کلیک بر روی دکمه ماژول نصب و فایل زیپ ماژول را انتخاب کنید.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_a9f902c1ce6abfbf5cd3573d49973d87'] = 'Prestashop نسخه فعلی خود را تشخیص و به روز رسانی به طور خودکار ماژول خود را.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3384251ff34a299aae3717020c8e0bfd'] = 'نیازی به حذف ماژول اول نیست.';
$_MODULE['<{ntbackupandrestore}prestashop>restoration_c4384e636370b73a93481c67d7b7b93d'] = 'هشدار! بایگانی فایل های ذکر شده در زیر در ریشه مغازه شما وجود دارد. این غیر معمول است. اگر آنها فایل های پشتیبان هستند، شما می توانید آنها را به ماژول با کلیک کردن بر روی دکمه حرکت حرکت می کند.';
