$_MODULE['<{ntbackupandrestore}prestashop>faq_e36bf213cae9b17180502b4611875cd6'] = 'اگر نرم افزار بدون خطا موفق به باز کردن فایل شود، فایل درست است. در غیر این صورت مشکلی در طول پشتیبان گیری وجود داشت.';
